package com.artofwar;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ScytheModelBuilder
{
    private static final Logger log = LoggerFactory.getLogger(ScytheModelBuilder.class);
    private static final int BASIC_MODEL = 823;
    private static final int TRANSPARENT_MODEL = 18871;
    private static final int PRIORITY_MODEL = 6733;

    @Inject
    private Client client;

    public Model build(ScytheModelData blender, int pitchDegrees, int rollDegrees)
    {
        if (blender == null || blender.vertices == null || blender.faces == null)
        {
            return null;
        }

        int vertexCount = blender.vertices.length;
        int faceCount = blender.faces.length;
        int[] verticesX = new int[vertexCount];
        int[] verticesY = new int[vertexCount];
        int[] verticesZ = new int[vertexCount];

        double pitch = Math.toRadians(pitchDegrees);
        double roll = Math.toRadians(rollDegrees);
        double pitchCos = Math.cos(pitch);
        double pitchSin = Math.sin(pitch);
        double rollCos = Math.cos(roll);
        double rollSin = Math.sin(roll);

        for (int i = 0; i < vertexCount; i++)
        {
            int[] vertex = blender.vertices[i];

            if (vertex == null || vertex.length < 3)
            {
                return null;
            }

            double x = vertex[0];
            double y = vertex[1];
            double z = vertex[2];

            double pitchedY = y * pitchCos - z * pitchSin;
            double pitchedZ = y * pitchSin + z * pitchCos;
            y = pitchedY;
            z = pitchedZ;

            double rolledX = x * rollCos - y * rollSin;
            double rolledY = x * rollSin + y * rollCos;
            x = rolledX;
            y = rolledY;

            verticesX[i] = (int) Math.round(x);
            verticesY[i] = (int) Math.round(y);
            verticesZ[i] = (int) Math.round(z);
        }

        int[] faces1 = new int[faceCount];
        int[] faces2 = new int[faceCount];
        int[] faces3 = new int[faceCount];

        for (int i = 0; i < faceCount; i++)
        {
            int[] face = blender.faces[i];

            if (face == null || face.length < 3)
            {
                return null;
            }

            faces1[i] = face[0];
            faces2[i] = face[1];
            faces3[i] = face[2];
        }

        int[] polys = {1, 0, 0, 0, 1};

        try
        {
            polys = getPolyCount(polys, faceCount - 3, vertexCount - 3);
        }
        catch (IllegalArgumentException ex)
        {
            log.error("Unable to construct model geometry.", ex);
            return null;
        }

        ModelData modelData = constructModel(polys);

        if (modelData == null
                || modelData.getVerticesCount() != vertexCount
                || modelData.getFaceCount() != faceCount)
        {
            return null;
        }

        float[] modelX = modelData.getVerticesX();
        float[] modelY = modelData.getVerticesY();
        float[] modelZ = modelData.getVerticesZ();
        int[] modelFace1 = modelData.getFaceIndices1();
        int[] modelFace2 = modelData.getFaceIndices2();
        int[] modelFace3 = modelData.getFaceIndices3();

        for (int i = 0; i < vertexCount; i++)
        {
            modelX[i] = verticesX[i];
            modelY[i] = verticesY[i];
            modelZ[i] = verticesZ[i];
        }

        for (int i = 0; i < faceCount; i++)
        {
            modelFace1[i] = faces1[i];
            modelFace2[i] = faces2[i];
            modelFace3[i] = faces3[i];
        }

        if (!applyFaceColours(blender, modelData))
        {
            return null;
        }

        Model model = modelData.light(64, 850, -30, -30, -50);

        if (model == null)
        {
            return null;
        }

        if (blender.priorities != null)
        {
            byte[] priorities = model.getFaceRenderPriorities();

            if (priorities != null)
            {
                int amount = Math.min(model.getFaceCount(), blender.priorities.length);

                for (int i = 0; i < amount; i++)
                {
                    priorities[i] = (byte) blender.priorities[i];
                }
            }
        }

        return model;
    }

    private boolean applyFaceColours(ScytheModelData blender, ModelData modelData)
    {
        if (blender.useVertexColours)
        {
            return true;
        }

        if (blender.faceColours == null
                || blender.faceColourIndex == null
                || blender.faceColourIndex.length < modelData.getFaceCount())
        {
            return false;
        }

        short[] colors = modelData.getFaceColors();
        byte[] transparencies = modelData.getFaceTransparencies();
        short[] palette = new short[blender.faceColours.length];
        byte[] transparencyPalette = new byte[blender.faceColours.length];

        for (int i = 0; i < blender.faceColours.length; i++)
        {
            double[] colour = blender.faceColours[i];

            if (colour == null || colour.length < 4)
            {
                continue;
            }

            int hue = (int) (63 - colour[0] * 63);
            int luminance = (int) (colour[1] * 127);
            int saturation = (int) (colour[2] * 7);

            palette[i] = JagexColor.packHSL(hue, saturation, luminance);

            double transparency = colour[3] * -256;

            if (transparency < -128)
            {
                transparency += 256;
            }

            transparencyPalette[i] = (byte) transparency;
        }

        for (int i = 0; i < modelData.getFaceCount(); i++)
        {
            int paletteIndex = blender.faceColourIndex[i];

            if (paletteIndex < 0 || paletteIndex >= palette.length)
            {
                return false;
            }

            colors[i] = palette[paletteIndex];

            if (transparencies != null)
            {
                transparencies[i] = transparencyPalette[paletteIndex];
            }
        }

        return true;
    }

    private int[] getPolyCount(int[] polys, int facesRemaining, int verticesRemaining)
    {
        if (facesRemaining == 0 && verticesRemaining == 0)
        {
            return polys;
        }

        if (facesRemaining < 0 || verticesRemaining < 0)
        {
            throw new IllegalArgumentException("Invalid model geometry.");
        }

        if (facesRemaining == 0)
        {
            throw new IllegalArgumentException("Invalid model geometry.");
        }

        double divisor = (double) verticesRemaining / facesRemaining;

        if (divisor == 3)
        {
            polys[1] += facesRemaining;
            return polys;
        }

        if (divisor == 2)
        {
            polys[2] += facesRemaining;
            return polys;
        }

        if (facesRemaining + 2 > verticesRemaining)
        {
            int change = facesRemaining + 2 - verticesRemaining;
            polys[3] += change;
            return getPolyCount(polys, facesRemaining - change, verticesRemaining);
        }

        if (verticesRemaining % 2 == 0)
        {
            polys[2]++;
            facesRemaining--;
            verticesRemaining -= 2;
        }
        else
        {
            polys[1]++;
            facesRemaining--;
            verticesRemaining -= 3;
        }

        return getPolyCount(polys, facesRemaining, verticesRemaining);
    }

    private ModelData constructModel(int[] polys)
    {
        List<ModelData> pieces = new ArrayList<>();

        ModelData priority = client.loadModelData(PRIORITY_MODEL);

        if (priority == null)
        {
            return null;
        }

        priority.cloneColors().cloneVertices();

        float[] priorityX = priority.getVerticesX();
        float[] priorityY = priority.getVerticesY();
        float[] priorityZ = priority.getVerticesZ();

        priorityX[0] = priorityX[1] = 64;
        priorityY[0] = priorityY[1] = 0;
        priorityZ[0] = priorityZ[1] = -64;

        priorityX[2] = priorityX[3] = -64;
        priorityY[2] = priorityY[3] = 0;
        priorityZ[2] = priorityZ[3] = 64;

        priorityX[4] = priorityX[5] = -64;
        priorityY[4] = priorityY[5] = 0;
        priorityZ[4] = priorityZ[5] = -64;

        pieces.add(priority);

        ModelData transparent = client.loadModelData(TRANSPARENT_MODEL);

        if (transparent == null)
        {
            return null;
        }

        transparent.cloneColors().cloneVertices().cloneTransparencies();

        float[] transparentX = transparent.getVerticesX();
        float[] transparentY = transparent.getVerticesY();
        float[] transparentZ = transparent.getVerticesZ();

        transparentX[0] = 64;
        transparentY[0] = 0;
        transparentZ[0] = -64;

        transparentX[1] = -64;
        transparentY[1] = 0;
        transparentZ[1] = 64;

        transparentX[2] = -64;
        transparentY[2] = 0;
        transparentZ[2] = -64;

        pieces.add(transparent);

        for (int i = 0; i < polys[1]; i++)
        {
            ModelData piece = client.loadModelData(BASIC_MODEL);

            if (piece == null)
            {
                return null;
            }

            piece.cloneColors().cloneVertices().translate(i + 1, i + 1, i + 1);
            pieces.add(piece);
        }

        for (int i = 0; i < polys[2]; i++)
        {
            ModelData piece = client.loadModelData(BASIC_MODEL);

            if (piece == null)
            {
                return null;
            }

            piece.cloneColors().cloneVertices().translate((i + 1) * 128, 0, 0);
            pieces.add(piece);
        }

        for (int i = 0; i < polys[3]; i++)
        {
            ModelData piece = client.loadModelData(BASIC_MODEL);

            if (piece == null)
            {
                return null;
            }

            piece.cloneColors().cloneVertices();
            pieces.add(piece);
        }

        return client.mergeModels(pieces.toArray(new ModelData[0]));
    }
}

package com.artofwar;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.Reader;
import net.runelite.client.util.Filepath;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Model;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.kit.KitType;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
		name = "Art of War",
		description = "scythe plugin",
		tags = {"scythe"},
		internalName = "art-of-war",
		legacyDataDirectory = "custom-weapon-models"
)
public class ArtOfWarPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(ArtOfWarPlugin.class);
	private static final Set<Integer> SUPPORTED_SCYTHE_IDS = Set.of(
			22486,
			22325,
			25736,
			25739
	);
	private static final int IDLE_ANIMATION_ID = 8057;
	private static final int WALK_ANIMATION_ID = 819;
	private static final int RUN_ANIMATION_ID = 824;
	private static final int ATTACK_ANIMATION_ID = 8056;
	private static final int DEFEND_ANIMATION_ID = 435;


	@Inject
	private ArtOfWarConfig config;

	@Inject
	private Gson gson;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ScytheModelBuilder scytheModelBuilder;

	@Inject
	private ScytheModelSpawner scytheModelSpawner;

	private ScytheModelData customModel;
	private Model renderedModel;
	private boolean targetWeaponEquipped;
	private boolean originalWeaponHidden;

	private final Map<String, Model> modelCache = new HashMap<>();

	@Override
	protected void startUp()
	{
		loadSelectedModel();
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			restoreOriginalWeaponIfStillEquipped();
			scytheModelSpawner.despawn();
		});

		targetWeaponEquipped = false;
		originalWeaponHidden = false;
		customModel = null;
		renderedModel = null;
		modelCache.clear();
	}

	private void loadSelectedModel()
	{
		ArtOfWarConfig.ScytheModel selection = config.scytheModel();
		Filepath modelFile;

		try
		{
			modelFile = getPluginDirectory().joinSegment(selection.getFileName());
		}
		catch (IOException | RuntimeException ex)
		{
			log.error("Failed to access Art of War model directory.", ex);
			return;
		}

		if (!modelFile.exists())
		{
			log.error("Scythe model not found: {}", modelFile);
			return;
		}

		ScytheModelData loadedModel;

		try (Reader reader = modelFile.openReader())
		{
			loadedModel = gson.fromJson(reader, ScytheModelData.class);
		}
		catch (IOException | RuntimeException ex)
		{
			log.error("Failed to load scythe model: {}", selection, ex);
			return;
		}

		if (loadedModel == null || loadedModel.vertices == null || loadedModel.faces == null)
		{
			log.error("Invalid scythe model: {}", modelFile);
			return;
		}

		clientThread.invokeLater(() ->
		{
			if (config.scytheModel() != selection)
			{
				return;
			}

			customModel = loadedModel;
			modelCache.clear();

			int[] idle = AnimationData.IDLE[0];
			renderedModel = getModel(idle[4], idle[5]);

			if (renderedModel == null)
			{
				log.error("Failed to build scythe model: {}", selection);
				return;
			}

			if (targetWeaponEquipped && scytheModelSpawner.isSpawned())
			{
				scytheModelSpawner.setModel(renderedModel);
			}

			syncEquipmentState();
		});
	}

	private Model getModel(int pitch, int roll)
	{
		if (customModel == null)
		{
			return null;
		}

		String key = pitch + ":" + roll;
		Model cached = modelCache.get(key);

		if (cached != null)
		{
			return cached;
		}

		Model model = scytheModelBuilder.build(customModel, pitch, roll);

		if (model != null)
		{
			modelCache.put(key, model);
		}

		return model;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("artofwarplugin".equals(event.getGroup()) && "scytheModel".equals(event.getKey()))
		{
			loadSelectedModel();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			checkEquipment(event.getItemContainer());
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!targetWeaponEquipped || !scytheModelSpawner.isSpawned())
		{
			return;
		}

		Player player = client.getLocalPlayer();

		if (player == null)
		{
			return;
		}

		hideOriginalWeapon();

		int actionAnimation = player.getAnimation();
		int actionFrame = player.getAnimationFrame();

		if (actionAnimation == DEFEND_ANIMATION_ID && actionFrame >= 0)
		{
			applyFrame(AnimationData.DEFEND, actionFrame);
			return;
		}

		if (actionAnimation == ATTACK_ANIMATION_ID && actionFrame >= 0)
		{
			applyFrame(AnimationData.ATTACK, actionFrame);
			return;
		}

		int poseAnimation = player.getPoseAnimation();
		int poseFrame = player.getPoseAnimationFrame();

		if (poseAnimation == RUN_ANIMATION_ID && poseFrame >= 0)
		{
			applyFrame(AnimationData.RUN, poseFrame);
			return;
		}

		if (poseAnimation == WALK_ANIMATION_ID && poseFrame >= 0)
		{
			applyFrame(AnimationData.WALK, poseFrame);
			return;
		}

		if (poseAnimation == IDLE_ANIMATION_ID && poseFrame >= 0)
		{
			applyFrame(AnimationData.IDLE, poseFrame);
			return;
		}

		applyFrame(AnimationData.IDLE, 0);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		if (state == GameState.LOADING)
		{
			scytheModelSpawner.despawn();
			originalWeaponHidden = false;
			return;
		}

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			targetWeaponEquipped = false;
			originalWeaponHidden = false;
			scytheModelSpawner.despawn();
			return;
		}

		if (state == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::syncEquipmentState);
		}
	}

	private void applyFrame(int[][] animation, int frame)
	{
		int[] transform = animation[Math.max(0, Math.min(frame, animation.length - 1))];
		Model model = getModel(transform[4], transform[5]);

		if (model != null)
		{
			renderedModel = model;
			scytheModelSpawner.setModel(model);
		}

		scytheModelSpawner.updateTransform(
				transform[0],
				transform[1],
				transform[2],
				transform[3]
		);
	}

	private void syncEquipmentState()
	{
		checkEquipment(client.getItemContainer(InventoryID.WORN));
	}

	private void checkEquipment(ItemContainer equipment)
	{
		if (equipment == null)
		{
			return;
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		boolean equipped = weapon != null && SUPPORTED_SCYTHE_IDS.contains(weapon.getId());

		if (equipped)
		{
			targetWeaponEquipped = true;
			hideOriginalWeapon();

			if (renderedModel != null && !scytheModelSpawner.isSpawned())
			{
				scytheModelSpawner.spawn(renderedModel);
			}

			return;
		}

		targetWeaponEquipped = false;
		originalWeaponHidden = false;
		scytheModelSpawner.despawn();
	}

	private void hideOriginalWeapon()
	{
		Player player = client.getLocalPlayer();

		if (player == null)
		{
			return;
		}

		PlayerComposition composition = player.getPlayerComposition();

		if (composition == null)
		{
			return;
		}

		int[] equipmentIds = composition.getEquipmentIds();
		int weaponIndex = KitType.WEAPON.getIndex();

		if (equipmentIds == null || weaponIndex < 0 || weaponIndex >= equipmentIds.length)
		{
			return;
		}

		if (equipmentIds[weaponIndex] != 0)
		{
			equipmentIds[weaponIndex] = 0;
			composition.setHash();
			originalWeaponHidden = true;
		}
	}

	private void restoreOriginalWeaponIfStillEquipped()
	{
		if (!originalWeaponHidden)
		{
			return;
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);

		if (equipment == null)
		{
			return;
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());

		if (weapon == null || !SUPPORTED_SCYTHE_IDS.contains(weapon.getId()))
		{
			return;
		}

		Player player = client.getLocalPlayer();

		if (player == null)
		{
			return;
		}

		PlayerComposition composition = player.getPlayerComposition();

		if (composition == null)
		{
			return;
		}

		int[] equipmentIds = composition.getEquipmentIds();
		int weaponIndex = KitType.WEAPON.getIndex();

		if (equipmentIds == null || weaponIndex < 0 || weaponIndex >= equipmentIds.length)
		{
			return;
		}

		equipmentIds[weaponIndex] = PlayerComposition.ITEM_OFFSET + weapon.getId();
		composition.setHash();
		originalWeaponHidden = false;
	}

	@Provides
	ArtOfWarConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ArtOfWarConfig.class);
	}
}

package com.artofwar;

public class ScytheModelData
{
    public boolean useVertexColours;
    public int[][] vertices;
    public int[][] faces;
    public double[][] vertexColours;
    public int[] vertexColourIndex;
    public double[][] faceColours;
    public int[] faceColourIndex;
    public int[] priorities;
    public int[] clientTicks;
    public int[][][] animVertices;
}

package com.artofwar;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;

public class ScytheModelSpawner
{
    private static final int FULL_ROTATION = 2048;
    private static final int RENDER_RADIUS = 255;

    @Inject
    private Client client;

    private RuneLiteObject spawnedObject;

    public void spawn(Model model)
    {
        if (model == null || client.getLocalPlayer() == null)
        {
            return;
        }

        despawn();

        spawnedObject = client.createRuneLiteObject();
        spawnedObject.setModel(model);
        spawnedObject.setRadius(RENDER_RADIUS);
        spawnedObject.setActive(true);
    }

    public void setModel(Model model)
    {
        if (spawnedObject != null && model != null)
        {
            spawnedObject.setModel(model);
        }
    }

    public void updateTransform(int side, int forward, int height, int yawDegrees)
    {
        if (!isSpawned())
        {
            return;
        }

        Player player = client.getLocalPlayer();

        if (player == null)
        {
            return;
        }

        LocalPoint playerLocation = player.getLocalLocation();

        if (playerLocation == null)
        {
            return;
        }

        int playerOrientation = player.getCurrentOrientation();
        double angle = playerOrientation * (2.0 * Math.PI / FULL_ROTATION);
        double sin = Math.sin(angle);
        double cos = Math.cos(angle);

        int rotatedX = (int) Math.round(side * cos + forward * sin);
        int rotatedY = (int) Math.round(forward * cos - side * sin);

        spawnedObject.setLocation(playerLocation, client.getPlane());
        spawnedObject.setX(spawnedObject.getX() + rotatedX);
        spawnedObject.setY(spawnedObject.getY() + rotatedY);
        spawnedObject.setZ(spawnedObject.getZ() + height);

        int yawUnits = (int) Math.round(yawDegrees * FULL_ROTATION / 360.0);
        int orientation = (playerOrientation + yawUnits) % FULL_ROTATION;

        if (orientation < 0)
        {
            orientation += FULL_ROTATION;
        }

        spawnedObject.setOrientation(orientation);
        spawnedObject.setRadius(RENDER_RADIUS);
    }

    public void despawn()
    {
        if (spawnedObject != null)
        {
            spawnedObject.setActive(false);
            spawnedObject = null;
        }
    }

    public boolean isSpawned()
    {
        return spawnedObject != null && spawnedObject.isActive();
    }
}

package com.artofwar;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("artofwar")
public interface ArtOfWarConfig extends Config
{
	enum ScytheModel
	{
		MAIDEN("Maiden", "maiden_scythe.json"),
		XARPUS("Xarpus", "xarpus_scythe.json");

		private final String label;
		private final String fileName;

